<header class="page-header"><div><p class="eyebrow">Campaign report</p><h1><?= $escape($campaign['name']) ?></h1><p><?= $escape($campaign['start_date']) ?> through <?= $escape($campaign['end_date']) ?>.</p></div></header>
<section><h2>Campaign progress</h2><div class="table-scroll"><table><thead><tr><th>Metric</th><th>Actual</th><th>Target</th></tr></thead><tbody><?php foreach ($report['targets'] as $target): ?><tr><th scope="row"><a href="<?= $escape($reportUrl . '?metric=' . rawurlencode($target['key'])) ?>"><?= $escape($target['label']) ?></a></th><td><?= $escape($target['actual']) ?></td><td><?= $escape($target['target']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section><h2>Conversion rates</h2><div class="table-scroll"><table><thead><tr><th>Rate</th><th>Result</th></tr></thead><tbody><?php foreach (['contact_to_response' => 'Contact → response', 'response_to_conversation' => 'Response → conversation', 'contact_to_conversation' => 'Contact → conversation', 'conversation_to_qualified' => 'Conversation → qualified opportunity', 'qualified_to_offer' => 'Qualified opportunity → offer', 'offer_to_won' => 'Offer → won'] as $key => $label): ?><?php $rate = $report['rates'][$key]; ?><tr><th scope="row"><?= $escape($label) ?></th><td><?= $rate['denominator'] === 0 ? 'Unavailable' : $escape(number_format(100 * $rate['numerator'] / $rate['denominator'], 1)) . '%' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section><h2>Pipeline value</h2><dl class="record-details"><div><dt>Open pipeline</dt><dd>$<?= $escape($report['pipeline']['open_value']) ?></dd></div><div><dt>Won value</dt><dd>$<?= $escape($report['pipeline']['won_value']) ?></dd></div></dl></section>
<?php if ($metric !== ''): ?><section><h2>Source records</h2><?php if ($drillDown === []): ?><p>No records contribute to this metric in the campaign period.</p><?php else: ?><ul><?php foreach ($drillDown as $row): ?><?php $url = $row['entity_type'] === 'opportunity' ? $opportunityUrl((int) $row['id']) : $prospectUrl((int) $row['id']); ?><li><a href="<?= $escape($url) ?>"><?= $escape($row['relationship_name'] ?: 'Unnamed relationship') ?></a></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
